set-variable.value:
@{
      try {
        var b = (JObject)context.Variables["reqBody"];
        var filename = (string)(b["filename"] ?? "");
        var supplied = (string)(b["contentType"] ?? "");
        var dot = filename.LastIndexOf(".");
        var extension = dot >= 0 ? filename.Substring(dot).ToLowerInvariant() : "";
        var separator = supplied.IndexOf(";");
        if (separator >= 0) { supplied = supplied.Substring(0, separator); }
        supplied = supplied.Trim().ToLowerInvariant();
        string expected = "";
        if (extension == ".pdf") { expected = "application/pdf"; }
        else if (extension == ".png") { expected = "image/png"; }
        else if (extension == ".jpg" || extension == ".jpeg") { expected = "image/jpeg"; }
        return supplied == expected ? expected : "";
      } catch { return ""; }
    }

@{
      try {
        var b = (JObject)context.Variables["reqBody"];
        var content = b["contentBase64"];
        if (content == null || content.Type != JTokenType.String) { return "invalid"; }
        var b64 = (string)content;
        if (string.IsNullOrEmpty(b64)) { return "invalid"; }
        if (b64.Length > 11184812) { return "too_large"; }
        var decoded = System.Convert.FromBase64String(b64);
        if (decoded.LongLength > 8388608) { return "too_large"; }
        if (decoded.Length < 8) { return "type_mismatch"; }
        var contentType = (string)context.Variables["validatedContentType"];
        if (contentType == "application/pdf") {
          return decoded[0] == 0x25 && decoded[1] == 0x50 && decoded[2] == 0x44 && decoded[3] == 0x46 && decoded[4] == 0x2D
            ? "ok" : "type_mismatch";
        }
        if (contentType == "image/png") {
          return decoded[0] == 0x89 && decoded[1] == 0x50 && decoded[2] == 0x4E && decoded[3] == 0x47
              && decoded[4] == 0x0D && decoded[5] == 0x0A && decoded[6] == 0x1A && decoded[7] == 0x0A
            ? "ok" : "type_mismatch";
        }
        if (contentType == "image/jpeg") {
          return decoded[0] == 0xFF && decoded[1] == 0xD8 && decoded[2] == 0xFF
            ? "ok" : "type_mismatch";
        }
        return "type_mismatch";
      } catch { return "invalid"; }
    }

send-request.set-body:
@{
        var b = (JObject)context.Variables["reqBody"];
        var b64 = (string)(b["contentBase64"] ?? "");
        return System.Convert.FromBase64String(b64);
      }

set-header.value:
@{
        var origin = context.Request.Headers.GetValueOrDefault("Origin","");
        return origin == "https://udcsp.fredgis.com"
            || origin == "https://icy-dune-01c23d903.7.azurestaticapps.net"
            || origin == "http://localhost:3000"
            || origin == "http://localhost:5173"
          ? origin
          : "https://udcsp.fredgis.com";
      }

return-response.set-body:
@{
        var pr = (IResponse)context.Variables["putResp"];
        var status = (int)pr.StatusCode;
        var blob = (string)context.Variables["blobName"];
        var url = "https://{{storage-account-name}}.blob.core.windows.net/citizen-uploads/" + blob;
        if (status >= 400) {
          var raw = pr.Body.As<string>(preserveContent: true);
          return new JObject(new JProperty("error", "upload_failed"), new JProperty("status", status), new JProperty("raw", raw)).ToString();
        }
        return new JObject(
          new JProperty("blobUrl", url),
          new JProperty("blobName", blob),
          new JProperty("container", "citizen-uploads"),
          new JProperty("storageAccount", "{{storage-account-name}}"),
          new JProperty("status", status)
        ).ToString();
      }

set-header.value:
@{
        var origin = context.Request.Headers.GetValueOrDefault("Origin","");
        return origin == "https://udcsp.fredgis.com"
            || origin == "https://icy-dune-01c23d903.7.azurestaticapps.net"
            || origin == "http://localhost:3000"
            || origin == "http://localhost:5173"
          ? origin
          : "https://udcsp.fredgis.com";
      }
